// Configuration
const maxChars = 10000;

const story = $input.all()[0].json.story;

// Split by paragraphs (double newline)
const paragraphs = story.split(/\n\n+/).filter(p => p.trim().length > 0);

const chunks = [];
let currentChunk = '';

for (const para of paragraphs) {
  const trimmedPara = para.trim();
  const testChunk = currentChunk ? currentChunk + '\n\n' + trimmedPara : trimmedPara;

  // If adding this paragraph exceeds limit and we have content, save current chunk
  if (testChunk.length > maxChars && currentChunk.length > 0) {
    chunks.push({
      text: currentChunk.trim()
    });
    currentChunk = trimmedPara;
  } 
  // If single paragraph exceeds limit, split by sentences
  else if (trimmedPara.length > maxChars && currentChunk.length === 0) {
    const sentences = trimmedPara.match(/[^.!?]+[.!?]+/g) || [trimmedPara];
    let sentenceChunk = '';

    for (const sentence of sentences) {
      const testSentence = sentenceChunk ? sentenceChunk + ' ' + sentence : sentence;

      if (testSentence.length > maxChars && sentenceChunk.length > 0) {
        chunks.push({
          text: sentenceChunk.trim()
        });
        sentenceChunk = sentence;
      } else {
        sentenceChunk = testSentence;
      }
    }
    currentChunk = sentenceChunk;
  } 
  else {
    currentChunk = testChunk;
  }
}

// Add final chunk
if (currentChunk.trim().length > 0) {
  chunks.push({
    text: currentChunk.trim()
  });
}

return chunks;

// items[0].json.candidates[0].content.parts[0].inlineData.data
const b64 = $json.candidates[0].content.parts[0].inlineData.data;
const buf = Buffer.from(b64, 'base64');

return [{
  json: {},
  binary: {
    // the key “audio” is arbitrary – you'll reference it below
    audio: {
      data: buf.toString('base64'),
      mimeType: 'audio/pcm',
      fileName: 'gemini_conversation.pcm',
    }
  }
}];

